#include <iostream>
#include <algorithm>
#include <vector>
#include <cstring>

using namespace std;

const long long MOD = 1000000007;
int baseK;
struct State {
    int mat[MAXK][MAXK];
    int inside[MAXK];
    bool exist[MAXK];

    State() {
        memset(mat, 0, sizeof(mat));
        memset(inside, 0, sizeof(inside));
        memset(exist, 0, sizeof(exist));
    }

    State(const State &other, int rot) {
        for (int i = 0; i < baseK; i++) {
            exist[(i + rot) % baseK] = other.exist[i];
            inside[(i + rot) % baseK] = other.inside[i];
            for (int j = 0; j < baseK; j++) {
                mat[(i + rot) % baseK][(j + rot) % baseK] = other.mat[i][j];
            }
        }
    }

    State(const State &a, const State &b) {
        for (int i = 0; i < baseK; i++) {
            exist[i] = a.exist[i] || b.exist[i];
            inside[i] = a.inside[i];
            if (!a.exist[i]) inside[i] = (inside[i] + b.inside[i]) % MOD;
            for (int j = 0; j < baseK; j++) {
                inside[i] = (inside[i] + (long long)a.mat[i][j] * b.inside[j]) % MOD;
                mat[i][j] = 0;
                if (!b.exist[j]) mat[i][j] = a.mat[i][j];
                if (!a.exist[i]) mat[i][j] = (mat[i][j] + b.mat[i][j]) % MOD;
                for (int m = 0; m < baseK; m++) {
                    mat[i][j] = (mat[i][j] + (long long)a.mat[i][m] * b.mat[m][j]) % MOD;
                }
            }
        }
    }
};

State power[MAXD];
int digits[MAXD];

int main() {
    long long n;
    cin >> n >> baseK;
    int length = 0;
    for (long long x = n; x > 0; x /= baseK) {
        digits[length++] = x % baseK;
    }
    power[0].exist[0] = true;
    power[0].inside[0] = 1;
    for (int j = 0; j < baseK; j++) {
        power[0].mat[0][j] = 1;
    }
    for (int i = 1; i < length; i++) {
        power[i] = power[i - 1];
        for (int v = 1; v < baseK; v++) {
            power[i] = State(power[i], State(power[i - 1], v));
        }
    }
    State result;
    int sum = 0;
    for (int i = length - 1; i >= 0; i--) {
        for (int v = 0; v < digits[i]; v++) {
            result = State(result, State(power[i], (sum + v) % baseK));
        }
        sum += digits[i];
    }
    long long total = 1;
    for (int i = 0; i < baseK; i++) {
        total = (total + result.inside[i]) % MOD;
    }
    cout << total << endl;
    return 0;
}
